namespace notify::json {
const Value* Value::find(std::string_view k) const { auto o=std::get_if<Object>(&data); if(!o)return nullptr; auto i=o->find(k);return i==o->end()?nullptr:&i->second; }
std::string Value::string_or(std::string f) const { auto p=std::get_if<std::string>(&data);return p?*p:std::move(f); }
double Value::number_or(double f) const { if(auto i=std::get_if<std::int64_t>(&data))return(double)*i;auto p=std::get_if<double>(&data);return p?*p:f; }
bool Value::is_null() const { return std::holds_alternative<std::nullptr_t>(data); }
bool valid_utf8(std::string_view s){for(size_t i=0;i<s.size();){unsigned char c=s[i];size_t n=c<0x80?1:(c>=0xC2&&c<=0xDF?2:(c>=0xE0&&c<=0xEF?3:(c>=0xF0&&c<=0xF4?4:0)));if(!n||i+n>s.size())return false;for(size_t j=1;j<n;j++)if((static_cast<unsigned char>(s[i+j])&0xC0)!=0x80)return false;if(n==3){auto d=static_cast<unsigned char>(s[i+1]);if((c==0xE0&&d<0xA0)||(c==0xED&&d>=0xA0))return false;}if(n==4){auto d=static_cast<unsigned char>(s[i+1]);if((c==0xF0&&d<0x90)||(c==0xF4&&d>=0x90))return false;}i+=n;}return true;}
class Parser { std::string_view s;size_t p=0,max_depth;[[noreturn]] void fail(){throw std::runtime_error("invalid JSON");}void ws(){while(p<s.size()&&(s[p]==' '||s[p]=='\r'||s[p]=='\n'||s[p]=='\t'))p++;}bool take(char c){ws();if(p<s.size()&&s[p]==c){p++;return true;}return false;}unsigned hex4(){if(p+4>s.size())fail();unsigned x=0;for(int i=0;i<4;i++){char c=s[p++];x<<=4;if(c>='0'&&c<='9')x|=c-'0';else if(c>='a'&&c<='f')x|=c-'a'+10;else if(c>='A'&&c<='F')x|=c-'A'+10;else fail();}return x;}void utf8(std::string&o,unsigned c){if(c<=0x7f)o+=(char)c;else if(c<=0x7ff){o+=(char)(0xc0|(c>>6));o+=(char)(0x80|(c&63));}else if(c<=0xffff){o+=(char)(0xe0|(c>>12));o+=(char)(0x80|((c>>6)&63));o+=(char)(0x80|(c&63));}else{o+=(char)(0xf0|(c>>18));o+=(char)(0x80|((c>>12)&63));o+=(char)(0x80|((c>>6)&63));o+=(char)(0x80|(c&63));}}std::string str(){if(!take('"'))fail();std::string o;while(p<s.size()){char c=s[p++];if(c=='"'){if(!valid_utf8(o))fail();return o;}if((unsigned char)c<0x20)fail();if(c!='\\'){o+=c;continue;}if(p==s.size())fail();char e=s[p++];switch(e){case '"':case '\\':case '/':o+=e;break;case 'b':o+='\b';break;case 'f':o+='\f';break;case 'n':o+='\n';break;case 'r':o+='\r';break;case 't':o+='\t';break;case 'u':{unsigned cp=hex4();if(cp>=0xd800&&cp<=0xdbff){if(p+2>s.size()||s[p++]!='\\'||s[p++]!='u')fail();unsigned lo=hex4();if(lo<0xdc00||lo>0xdfff)fail();cp=0x10000+((cp-0xd800)<<10)+(lo-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff)fail();utf8(o,cp);break;}default:fail();}}fail();}
 Value value(size_t d){if(d>max_depth)fail();ws();if(p==s.size())fail();if(s[p]=='"'){Value v;v.data=str();return v;}if(s[p]=='{'){p++;Value::Object o;if(take('}')){Value v;v.data=std::move(o);return v;}do{auto k=str();if(!take(':'))fail();if(!o.emplace(std::move(k),value(d+1)).second)fail();}while(take(','));if(!take('}'))fail();Value v;v.data=std::move(o);return v;}if(s[p]=='['){p++;Value::Array a;if(take(']')){Value v;v.data=std::move(a);return v;}do{if(a.size()>100000)fail();a.push_back(value(d+1));}while(take(','));if(!take(']'))fail();Value v;v.data=std::move(a);return v;}if(s.substr(p,4)=="true"){p+=4;Value v;v.data=true;return v;}if(s.substr(p,5)=="false"){p+=5;Value v;v.data=false;return v;}if(s.substr(p,4)=="null"){p+=4;return{};}size_t b=p;if(s[p]=='-')p++;if(p==s.size()||s[p]<'0'||s[p]>'9')fail();if(s[p]=='0')p++;else while(p<s.size()&&s[p]>='0'&&s[p]<='9')p++;if(p<s.size()&&s[p]=='.'){p++;size_t x=p;while(p<s.size()&&isdigit((unsigned char)s[p]))p++;if(p==x)fail();}if(p<s.size()&&(s[p]=='e'||s[p]=='E')){p++;if(p<s.size()&&(s[p]=='+'||s[p]=='-'))p++;size_t x=p;while(p<s.size()&&isdigit((unsigned char)s[p]))p++;if(p==x)fail();}bool fractional=s.substr(b,p-b).find_first_of(".eE")!=std::string_view::npos;Value v;if(!fractional){std::int64_t i;auto [q,ec]=std::from_chars(s.data()+b,s.data()+p,i);if(ec!=std::errc{}||q!=s.data()+p)fail();v.data=i;}else{double n;auto [q,ec]=std::from_chars(s.data()+b,s.data()+p,n);if(ec!=std::errc{}||q!=s.data()+p||!std::isfinite(n))fail();v.data=n;}return v;}
public:Parser(std::string_view x,size_t d):s(x),max_depth(d){}Value run(){if(!valid_utf8(s))fail();auto v=value(0);ws();if(p!=s.size())fail();return v;}};
Value parse(std::string_view s,size_t max,size_t depth){if(s.size()>max)throw std::runtime_error("JSON size limit");return Parser(s,depth).run();}
static void quote(std::string& o,std::string_view s){o+='"';for(unsigned char c:s){if(c=='"'||c=='\\'){o+='\\';o+=(char)c;}else if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else if(c=='\t')o+="\\t";else if(c<0x20){char b[7];std::snprintf(b,sizeof b,"\\u%04x",c);o+=b;}else o+=(char)c;}o+='"';}
static void emit(std::string& o,const Value& v){if(v.is_null()){o+="null";return;}if(auto p=std::get_if<bool>(&v.data)){o+=*p?"true":"false";return;}if(auto p=std::get_if<std::int64_t>(&v.data)){char b[64];auto r=std::to_chars(b,b+64,*p);o.append(b,r.ptr);return;}if(auto p=std::get_if<double>(&v.data)){if(!std::isfinite(*p))throw std::runtime_error("nonfinite JSON number");char b[64];auto r=std::to_chars(b,b+64,*p);o.append(b,r.ptr);return;}if(auto p=std::get_if<std::string>(&v.data)){quote(o,*p);return;}if(auto p=std::get_if<Value::Array>(&v.data)){o+='[';bool f=true;for(auto& x:*p){if(!f)o+=',';f=false;emit(o,x);}o+=']';return;}auto& m=std::get<Value::Object>(v.data);o+='{';bool f=true;for(auto& [k,x]:m){if(!f)o+=',';f=false;quote(o,k);o+=':';emit(o,x);}o+='}';}
std::string stringify(const Value& v){std::string o;emit(o,v);return o;}
}
